type Exp = u128;
struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: u128,
    pub self_steps: u64,
}
impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s_exp = match *self {
            Run(_, n) => if n == 1 { "" } else { &format!("^{}", n) }
            _ => "",
        };
        write!(f, "{}{}", s0, s_exp)
    }
}

// End of customizable code

impl BlockSimulator {
    pub fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, Run(D, 1)],
            right_tape: vec![R, Run(W, 1)],
            state: HigherState::Right,
            base_steps: 10,
            self_steps: 0
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }

    pub fn parse_right_tape_exponents(&self) -> Option<(Exp, Exp)> {
        use BlockSymbol::*;
        use RunSymbolType::*;
        match self.right_tape.as_slice() {
            [R] => Some((0,0)),
            [R, Run(W, m)] => Some((*m, 0)),
            [R, Run(V, n)] => Some((0, *n)),
            [R, Run(V, n), Run(W, m)] => Some((*m, *n)),
            _ => None,
        }
    }
}

