type RightExp = u32;
type IRExp = i32;

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
struct RightTapeOutcome {
    head: LeftReturningHead,
    m: RightExp,
    n: RightExp,
}

impl fmt::Display for RightTapeOutcome {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{} {},{}", self.head, self.m, self.n)
    }
}

fn calculate_right_tape_outcome(m0: Exp, n0: Exp, initial_state: HigherState) -> RightTapeOutcome {
    use BlockSymbol::*;
    use RunSymbolType::*;
    use HigherState::*;

    let mut sim = BlockSimulator {
        left_tape: vec![],
        right_tape: vec![R],
        state: initial_state,
        base_steps: 0,
        self_steps: 0
    };

    if n0 > 0 {
        sim.right_tape.push(Run(V, n0));
    }
    if m0 > 0 {
        sim.right_tape.push(Run(W, m0));
    }

    loop {
        let head = match (&sim.state, sim.left_tape.as_slice()) {
            (Left, []) => Some(LeftReturningHead::Left),
            (LeftC, []) => Some(LeftReturningHead::C),
            (LeftC, [U]) => Some(LeftReturningHead::Uc),
            (LeftC, [Run(C, 1)]) => Some(LeftReturningHead::Cc),
            _ => None,
        };
        if let Some(head) = head {
            let (m, n) = sim.parse_right_tape_exponents().unwrap();
            return RightTapeOutcome { head, m: m as RightExp, n: n as RightExp };
        }

        sim.step().unwrap();
        // println!("{sim}");
    }
}

