#[test]
fn test_outcomes() {
    let mut memo = NaiveMemo::new();
    for total in 0..22 {
        for n0 in 0..=total {
            let m0 = total - n0;
            let outcome = calculate_right_tape_outcome(m0, n0, HigherState::Right);
            let outcome2 = memo.get_or_calculate(HigherState::Right, m0 as RightExp, n0 as RightExp);
            assert_eq!(outcome, outcome2);
        }
    }
}
